import zipfile
import re
import xml.etree.ElementTree as ET

MAIN = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
REL = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'
PKGREL = '{http://schemas.openxmlformats.org/package/2006/relationships}'

path = 'budget.xlsx'
z = zipfile.ZipFile(path)
names = z.namelist()

shared = []
if 'xl/sharedStrings.xml' in names:
    root = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in root.findall(MAIN + 'si'):
        text = ''.join(t.text or '' for t in si.iter() if t.tag in (MAIN + 't', 't'))
        shared.append(text)

wb = ET.fromstring(z.read('xl/workbook.xml'))
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
relmap = {r.get('Id'): r.get('Target') for r in rels}

def sheet_path(target):
    if target.startswith('/'):
        return target.lstrip('/')
    return 'xl/' + target

def col_index(letters):
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord('A') + 1)
    return idx - 1

def cell_value(c):
    t = c.get('t', 'n')
    v = c.find(MAIN + 'v')
    if t == 's':
        return shared[int(v.text)] if v is not None else ''
    if t == 'inlineStr':
        is_ = c.find(MAIN + 'is')
        if is_ is not None:
            return ''.join(x.text or '' for x in is_.iter() if x.tag in (MAIN + 't', 't'))
        return ''
    if t == 'str':
        return v.text if v is not None else ''
    if t == 'b':
        return (v.text == '1') if v is not None else ''
    if t == 'e':
        return None
    if v is not None:
        return float(v.text)
    return ''

def to_num(val):
    if isinstance(val, (int, float)):
        return float(val)
    if isinstance(val, str):
        s = val.strip().replace('$', '').replace(',', '')
        try:
            return float(s)
        except ValueError:
            return None
    return None

sheets_info = []
for sh in wb.iter():
    if sh.tag == MAIN + 'sheet':
        sheets_info.append((sh.get('name'), sh.get(REL + 'id')))

grand = 0.0
print('SHEET NAMES:', [n for n, _ in sheets_info])
for name, rid in sheets_info:
    target = sheet_path(relmap.get(rid, ''))
    if target not in names:
        print(f'\n=== Sheet: {name} (MISSING FILE {target}) ===')
        continue
    root = ET.fromstring(z.read(target))
    grid = {}
    maxrow = 0
    maxcol = 0
    for row in root.iter(MAIN + 'row'):
        r = int(row.get('r', maxrow + 1))
        maxrow = max(maxrow, r)
        for c in row.findall(MAIN + 'c'):
            ref = c.get('r')
            m = re.match(r'([A-Z]+)(\d+)', ref or '')
            if not m:
                continue
            ci = col_index(m.group(1))
            ri = int(m.group(2))
            maxcol = max(maxcol, ci)
            grid[(ri, ci)] = cell_value(c)
    print(f'\n=== Sheet: {name} ===')
    for ri in range(1, maxrow + 1):
        cells = []
        for ci in range(maxcol + 1):
            v = grid.get((ri, ci), '')
            cells.append('' if v is None else str(v))
        print(f'R{ri}: ' + ' | '.join(cells))
    total = sum(to_num(v) for v in grid.values() if to_num(v) is not None)
    print(f'--- Sum of numeric cells in "{name}": {total}')
    grand += total
print(f'\nGRAND TOTAL OF ALL NUMERIC CELLS: {grand}')

