            grid[(ri, ci)] = cell_value(c)
    print(f'\n=== Sheet: {name} ===')
    for ri in range(1, maxrow + 1):
        cells = []
        for ci in range(maxcol + 1):
            v = grid.get((ri, ci), '')
            cells.append('' if v is None else str(v))
        print(f'R{ri}: ' + ' | '.join(cells))
    total = sum(to_num(v) for v in grid.values() if to_num(v) is not None)
    print(f'--- Sum of numeric cells in "{name}": {total}')
    grand += total
print(f'\nGRAND TOTAL OF ALL NUMERIC CELLS: {grand}')

import zipfile
import re
import xml.etree.ElementTree as ET

MAIN = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
REL = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'

z = zipfile.ZipFile('budget.xlsx')
names = z.namelist()
shared = []
if 'xl/sharedStrings.xml' in names:
    root = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in root.findall(MAIN + 'si'):
        shared.append(''.join(t.text or '' for t in si.iter() if t.tag in (MAIN + 't', 't')))

wb = ET.fromstring(z.read('xl/workbook.xml'))
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
relmap = {r.get('Id'): r.get('Target') for r in rels}

def col_index(letters):
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord('A') + 1)
    return idx - 1

def cell_value(c):
    t = c.get('t', 'n')
    v = c.find(MAIN + 'v')
    if t == 's':
        return shared[int(v.text)] if v is not None and v.text is not None else ''
    if t == 'inlineStr':
        is_ = c.find(MAIN + 'is')
        return ''.join(x.text or '' for x in is_.iter() if x.tag in (MAIN + 't', 't')) if is_ is not None else ''
    if t == 'str':
        return v.text if v is not None else ''
    if t == 'b':
        return (v.text == '1') if v is not None else ''
    if v is not None and v.text is not None:
        try:
            return float(v.text)
        except ValueError:
            return v.text
    return ''

def to_num(val):
    if isinstance(val, (int, float)):
        return float(val)
    if isinstance(val, str):
        try:
            return float(val.strip().replace('$', '').replace(',', ''))
        except ValueError:
            return None
    return None

rid = next(sh.get(REL + 'id') for sh in wb.iter() if sh.tag == MAIN + 'sheet')
target = relmap[rid]
if target.startswith('/'):
    target = target.lstrip('/')
else:
    target = 'xl/' + target
root = ET.fromstring(z.read(target))
grid = {}
for row in root.iter(MAIN + 'row'):
    for c in row.findall(MAIN + 'c'):
        m = re.match(r'([A-Z]+)(\d+)', c.get('r', ''))
        if m:
            grid[(int(m.group(2)), col_index(m.group(1)))] = cell_value(c)

# Expense rows 11-22 per the inspected layout: column C (index 2) holds amounts
total = 0.0
print('Expense detail:')
for ri in range(11, 23):
    cat = grid.get((ri, 0), '')
    item = grid.get((ri, 1), '')
    amt = to_num(grid.get((ri, 2), ''))
    if amt is not None:
        total += amt
        print(f'  {cat} | {item}: {amt:g}')
print(f'TOTAL EXPENSES (rows 11-22): {total:g}')
